from collections import Counter


def bestsellers(log, k):
    """Return the k best sellers as (product, count) tuples.

    Ranking rule: scan count descending, then earliest
    first scan wins the tie.
    """
    counts = Counter(log)
    first_index = {}
    for i, product in enumerate(log):
        if product not in first_index:
            first_index[product] = i
    ranked = sorted(counts, key=lambda p: (-counts[p], first_index[p]))
    return [(p, counts[p]) for p in ranked[:k]]
